const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Washington state geometry (rough polygon)
  const washington = ee.Geometry.Polygon([
    [-124.7, 48.2], [-124.7, 45.5], [-116.9, 45.5], 
    [-116.9, 49.0], [-124.7, 48.2]
  ]);

  // Define dates
  const date1 = '2021-11-15';
  const date2 = '2021-11-22';

  // Get SMAP soil moisture data
  const smap1 = ee.ImageCollection('NASA/SMAP/SPL3SMP_E')
    .filterDate(date1, ee.Date(date1).advance(1, 'day'))
    .filterBounds(washington);

  const smap2 = ee.ImageCollection('NASA/SMAP/SPL3SMP_E')
    .filterDate(date2, ee.Date(date2).advance(1, 'day'))
    .filterBounds(washington);

  // Check collection sizes
  const count1 = smap1.size().getInfo();
  const count2 = smap2.size().getInfo();

  print(`${date1} Images: ${count1}`);
  print(`${date2} Images: ${count2}`);

  if (count1 === 0 || count2 === 0) {
    print("<answer>C1</answer>");
    return;
  }

  // Get first image from each collection
  const img1 = smap1.first();
  const img2 = smap2.first();

  // Extract soil moisture values
  const soilMoisture1 = img1.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: washington,
    scale: 1000,
    maxPixels: 1e9
  }).get('soil_moisture_am');

  const soilMoisture2 = img2.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: washington,
    scale: 1000,
    maxPixels: 1e9
  }).get('soil_moisture_am');

  // Get pixel counts for validation
  const countPixels1 = img1.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: washington,
    scale: 1000,
    maxPixels: 1e9
  }).get('soil_moisture_am');

  const countPixels2 = img2.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: washington,
    scale: 1000,
    maxPixels: 1e9
  }).get('soil_moisture_am');

  const sm1 = soilMoisture1.getInfo();
  const sm2 = soilMoisture2.getInfo();
  const px1 = countPixels1.getInfo();
  const px2 = countPixels2.getInfo();

  print(`Nov 15 Soil Moisture: ${sm1 ? sm1.toFixed(4) : 'null'}, Pixels: ${px1}`);
  print(`Nov 22 Soil Moisture: ${sm2 ? sm2.toFixed(4) : 'null'}, Pixels: ${px2}`);

  // Check for no valid pixels
  if (px1 === 0 || px2 === 0) {
    print("<answer>C2</answer>");
    return;
  }

  // Check for calculation failures
  if (sm1 === null || sm2 === null || isNaN(sm1) || isNaN(sm2)) {
    print("<answer>C3</answer>");
    return;
  }

  // Compare soil moisture values
  if (sm2 > sm1) {
    print("<answer>A</answer>");
  } else {
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
